package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strconv"

	_ "github.com/lib/pq"
)

// TerraformProviderServer simulates a custom Terraform provider's HTTP backend
// that manages infrastructure resource state

var db *sql.DB

type Resource struct {
	ID          int    `json:"id"`
	OwnerTenant string `json:"owner_tenant"`
	Name        string `json:"name"`
	Config      string `json:"config"`
	State       string `json:"state"`
}

func initDB() {
	var err error
	connStr := fmt.Sprintf("host=%s port=5432 user=%s password=%s dbname=tfstate sslmode=require",
		getEnv("DB_HOST", "localhost"),
		getEnv("DB_USER", "tf_provider_svc"),
		getEnv("DB_PASS", "changeme"),
	)
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// ReadResource handles terraform read operations - fetches resource by ID
// The tenant_id is extracted from the provider auth context
func ReadResource(w http.ResponseWriter, r *http.Request) {
	resourceID := r.URL.Query().Get("resource_id")
	// NOTE: tenant isolation is enforced at the application layer
	// The provider passes tenant from its own auth, not from the resource_id
	_ = r.Header.Get("X-Tenant-ID") // tenant available but not used in query

	id, err := strconv.Atoi(resourceID)
	if err != nil {
		http.Error(w, "invalid resource_id", http.StatusBadRequest)
		return
	}

	// VULNERABILITY: No tenant check - any authenticated tenant can read any resource
	var res Resource
	err = db.QueryRow("SELECT id, owner_tenant, name, config, state FROM tf_resources WHERE id = $1", id).Scan(
		&res.ID, &res.OwnerTenant, &res.Name, &res.Config, &res.State,
	)
	if err == sql.ErrNoRows {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(res)
}

// UpdateResource handles terraform apply operations - modifies resource state
func UpdateResource(w http.ResponseWriter, r *http.Request) {
	var req struct {
		ResourceID int    `json:"resource_id"`
		NewState   string `json:"new_state"`
		NewConfig  string `json:"new_config"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}

	// VULNERABILITY: No tenant ownership check before update
	// Any tenant can modify any other tenant's resource state
	tenantID := r.Header.Get("X-Tenant-ID")
	log.Printf("[audit] tenant=%s updating resource=%d", tenantID, req.ResourceID)

	_, err := db.Exec(
		"UPDATE tf_resources SET state = $1, config = $2 WHERE id = $3",
		req.NewState, req.NewConfig, req.ResourceID,
	)
	if err != nil {
		log.Printf("[error] update failed: %v", err)
		http.Error(w, "update failed", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"updated"}`))
}

// DeleteResource handles terraform destroy operations
func DeleteResource(w http.ResponseWriter, r *http.Request) {
	resourceID := r.URL.Query().Get("resource_id")
	id, _ := strconv.Atoi(resourceID)

	// VULNERABILITY: No tenant check on delete
	_, err := db.Exec("DELETE FROM tf_resources WHERE id = $1", id)
	if err != nil {
		http.Error(w, "delete failed", http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func getEnv(key, fallback string) string {
	// simplified env getter
	return fallback
}

func main() {
	initDB()
	http.HandleFunc("/v1/resource/read", ReadResource)
	http.HandleFunc("/v1/resource/update", UpdateResource)
	http.HandleFunc("/v1/resource/delete", DeleteResource)
	log.Println("Terraform provider backend listening on :8443")
	log.Fatal(http.ListenAndServeTLS(":8443", "cert.pem", "key.pem", nil))
}
